#!/usr/bin/env bash
#
# Pull the latest code and put it live.
#
# `git pull` on its own is NOT enough, for two reasons that are easy to miss:
#
#   1. Asterisk reads /etc/asterisk, not this repo. A new dialplan context or
#      a new amd.conf sits in the working tree doing nothing until it is
#      copied across and reloaded.
#   2. Node has the old code in memory until the service restarts.
#
# And one thing this script deliberately does NOT do: copy pjsip.conf.
# That file is GENERATED by the UI from your saved trunks. The copy in this
# repo is an empty placeholder, so copying it over would delete every trunk
# you have configured. Trunk changes go live when you press Save on the
# Trunks tab, which rewrites it and reloads PJSIP.
#
# Re-exec under bash if this was started with `sh` (dash on Debian/Ubuntu).
# `set -o pipefail` is a bashism and dash aborts on it with "Illegal option",
# which reads like a bug in the script rather than the wrong interpreter.
[ -n "${BASH_VERSION:-}" ] || exec bash "$0" "$@"

set -euo pipefail

cd "$(dirname "$0")/.."
REPO="$(pwd)"
SERVICE="shadowpbx-campaign"
ETC="/etc/asterisk"

say() { printf '\n\033[1;36m==> %s\033[0m\n' "$*"; }
warn() { printf '\033[1;33m    ! %s\033[0m\n' "$*"; }

[ "$(id -u)" -eq 0 ] || { echo "Run this as root."; exit 1; }

say "Pulling the latest code"
BEFORE="$(git rev-parse HEAD)"
git pull --ff-only
AFTER="$(git rev-parse HEAD)"
if [ "$BEFORE" = "$AFTER" ]; then
  echo "    already up to date ($(git log --oneline -1))"
else
  git --no-pager log --oneline "$BEFORE..$AFTER" | sed 's/^/    /'
fi

# Install whenever what is in node_modules does not match package.json --
# not only when THIS run's pull changed it. Gating on the pull missed the
# common case of `git pull` by hand followed by update.sh: the script then saw
# nothing new, skipped the install, and the app crashed on a package that was
# never fetched. `npm ls` answers the real question whoever pulled.
if ! git diff --quiet "$BEFORE" "$AFTER" -- package.json package-lock.json 2>/dev/null \
   || ! npm ls --omit=dev --depth=0 >/dev/null 2>&1; then
  say "Installing dependencies"
  npm install --omit=dev --no-audit --no-fund
  npm ls --omit=dev --depth=0 >/dev/null 2>&1 \
    || warn "npm still reports missing or mismatched packages — check the output above"
else
  echo "    dependencies already match package.json"
fi

say "Updating Asterisk config"
# Same substitution the installer uses, so a config referencing ${ARI_PASS}
# lands with the real value rather than the literal text.
set -a; [ -f .env ] && . ./.env; set +a
VARS='${TRUNK_HOST} ${TRUNK_USER} ${TRUNK_PASS} ${PBX_HOST} ${PBX_PORT} ${ARI_PASS}'

# ari.conf embeds ${ARI_PASS}. If .env is missing or the variable is unset,
# envsubst happily writes `password = ` and ARI stops authenticating at the
# NEXT Asterisk restart -- a landmine that goes off hours later, nowhere near
# the deploy that planted it. Refuse instead.
if [ -z "${ARI_PASS:-}" ]; then
  warn "ARI_PASS is not set in .env — skipping Asterisk config so ari.conf is not blanked"
  SKIP_CONF=1
else
  SKIP_CONF=0
fi

CHANGED=0
DIALPLAN=0
ARICONF=0
for f in extensions.conf ari.conf http.conf rtp.conf amd.conf; do
  [ "$SKIP_CONF" -eq 1 ] && break
  [ -f "asterisk/$f" ] || continue
  TMP="$(mktemp)"
  envsubst "$VARS" < "asterisk/$f" > "$TMP"
  if [ -f "$ETC/$f" ] && cmp -s "$TMP" "$ETC/$f"; then
    rm -f "$TMP"; continue
  fi
  [ -f "$ETC/$f" ] && cp "$ETC/$f" "$ETC/$f.bak-$(date +%F-%H%M%S)"
  mv "$TMP" "$ETC/$f"; chmod 640 "$ETC/$f"
  echo "    updated $f"
  CHANGED=1
  [ "$f" = "extensions.conf" ] && DIALPLAN=1
  case "$f" in ari.conf|http.conf) ARICONF=1 ;; esac
done
[ "$CHANGED" -eq 0 ] && echo "    no changes"
echo "    (pjsip.conf left alone — the UI owns it; press Save on a trunk to rewrite it)"

if [ "$CHANGED" -eq 1 ]; then
  say "Reloading Asterisk"
  [ "$DIALPLAN" -eq 1 ] && asterisk -rx "dialplan reload" | sed 's/^/    /'
  # Reloading a module that was never loaded is not an error worth stopping
  # for -- AMD is optional and the app falls back to treating every call as
  # human when it is missing.
  asterisk -rx "module reload app_amd.so" >/dev/null 2>&1 \
    || warn "app_amd.so not loaded — answering-machine detection will pass every call through as human"

  # Copying http.conf or ari.conf changes nothing until they are reloaded.
  # Without this the new file sits on disk looking applied, and only takes
  # effect at the next Asterisk restart -- usually a crash, at the worst
  # possible moment.
  if [ "$ARICONF" -eq 1 ]; then
    asterisk -rx "module reload res_ari.so" >/dev/null 2>&1 || true
    asterisk -rx "module reload http" >/dev/null 2>&1 || true
    echo "    reloaded ARI and the HTTP server"
  fi
fi

say "Restarting $SERVICE"
systemctl restart "$SERVICE"
sleep 2
if systemctl is-active --quiet "$SERVICE"; then
  echo "    running — $(git log --oneline -1)"
else
  warn "service did not come back up:"
  journalctl -u "$SERVICE" -n 20 --no-pager | sed 's/^/    /'
  exit 1
fi

say "Checking ARI"
ARI_URL_C="${ARI_URL:-http://127.0.0.1:8088}"
if curl -fsS -m 5 -u "${ARI_USER:-campaign}:${ARI_PASS:-}" \
     "$ARI_URL_C/ari/asterisk/info" >/dev/null 2>&1; then
  echo "    ARI is answering at $ARI_URL_C"
else
  warn "ARI is NOT answering at $ARI_URL_C — the campaign engine cannot place calls."
  warn "Check:  systemctl status asterisk"
  warn "        asterisk -rx \"http show status\""
  warn "        asterisk -rx \"ari show users\""
fi

say "Done"
echo "    Settings stored in data/ and config/ are untouched."
echo "    Anything set in the UI (trunks, flows, campaigns) is unchanged."
